const tabId = 730410078;

const result = await browserjs(tabId, async () => {
  const iframe = document.getElementById('iframe_content');
  const win = iframe.contentWindow;
  const doc = iframe.contentDocument || win.document;

  const log = [];

  while (win.currentQuestion < win.noOfQuestions) {
    const qIndex = win.currentQuestion;
    const q = win.questions[qIndex];
    const a = q[0];
    const b = q[1];
    const expected = q[2];
    const answer = (a * b).toString();

    log.push({ qIndex: qIndex + 1, equation: `${a} x ${b}`, expected, answer });

    // Fill input
    const input = doc.getElementById('userAnswer');
    if (!input) {
      log.push({ error: "no userAnswer input" });
      break;
    }
    input.value = answer;

    // Reset enterKeyOrSubmitButtonClickedTime if needed to bypass debounce safely
    win.enterKeyOrSubmitButtonClickedTime = 0;

    // Trigger submit
    const submitBtn = doc.getElementById('submit');
    submitBtn.click();

    // Wait for the transition (500ms delay + buffer)
    await new Promise(r => setTimeout(r, 800));

    // Check if we are at the last question where #results appears
    if (qIndex + 1 === win.noOfQuestions) {
      // Results button should be displayed
      await new Promise(r => setTimeout(r, 500));
      const resultsBtn = doc.getElementById('results');
      if (resultsBtn && resultsBtn.style.display !== 'none') {
        resultsBtn.click();
        log.push({ message: "Clicked results button" });
      }
      break;
    }
  }

  return {
    log,
    finalState: {
      currentQuestion: win.currentQuestion,
      noOfQuestions: win.noOfQuestions,
      userAnswers: win.userAnswers,
      score: win.score,
      scorePercentage: win.scorePercentage
    }
  };
});

console.log(JSON.stringify(result, null, 2));

